package main

import (
	"fmt"
)

func generateReceiveLog(msg string) string {
	timestamp := "2023-10-05T12:34:56.789Z" // Simulated timestamp for demonstration
	return "[" + timestamp + "] Received: " + msg
}

// Test cases to simulate log injection attempts
func main() {
	// Test case 1: Normal message
	fmt.Println(generateReceiveLog("Hello, World!"))

	// Test case 2: Message with control characters
	fmt.Println(generateReceiveLog("\n\nNew Line Injection"))

	// Test case 3: Message with special characters
	fmt.Println(generateReceiveLog("Log[Injection] Attempt"))
}

go
func main() {
    // Test with a normal message
    log1 := generateReceiveLog("Hello, World!")
    println(log1)

    // Test with an empty message
    log2 := generateReceiveLog("")
    println(log2)

    // Test with special characters
    log3 := generateReceiveLog("Message with \n newlines and \" quotes.")
    println(log3)
}
